#!/usr/bin/env python3
"""FilterHub Phase 3 — canonical SKU dataset generator.

Single source of truth for the SKU database. Reads the curated product records
below and emits:

  filterhub/src/data/products.json        (canonical, Astro main site)
  data.filterhub/data/products.json       (byte-identical sync copy)

Discipline (zero fabrication):
  - Every sku/name/category/company/source_url is transcribed from the 5-site
    crawl corpus (2026-10-29). Product pages whose spec/material/filter-media
    fields the source does not publish keep those fields empty and are marked
    `pending` — never guessed.
  - efficiency_class is populated ONLY where the source labels it (e.g. H13/H14,
    G1-G4, M5-M9, F7-F9, U15-U17, MERV, F5).
  - Category codes map to the 13 main categories (Phase 2 taxonomy). Finer
    granularity is carried in `subcategory` (metal / membrane / ffu / v-bank …).
"""
import json
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
FILTERHUB_OUT = os.path.join(ROOT, "src", "data", "products.json")
DATAHUB_OUT = os.path.join(
    os.path.dirname(ROOT), "data.filterhub", "data", "products.json"
)

