def main():
    payload = {
        "_meta": {
            "description": "FilterHub 结构化 SKU 数据库 —— 从 5 站深度抓取（2026-10-29）提取的真实产品记录。无据字段保持空值并标 pending，不虚构。",
            "crawl_date": "2026-10-29",
            "sources": [
                "https://www.hbxueyuan.com/",
                "https://airyfilter.com/",
                "https://www.klcintl.com/",
                "https://www.yitong-filter.com/",
                "https://www.cleanroom-ffu.com/",
            ],
            "data_status_system": ["verified", "catalog-confirmed", "reference", "pending"],
            "categories": CATEGORY_META,
            "note": "category 映射 13 主品类（Phase 2 品类树）；subcategory 承载更细粒度（metal/membrane/ffu/v-bank/powercore 等）。efficiency_class 仅在来源目录标注时填充。",
        },
        "products": PRODUCTS,
    }

    text = json.dumps(payload, ensure_ascii=False, indent=2) + "\n"

    for path in (FILTERHUB_OUT, DATAHUB_OUT):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            f.write(text)

    print(f"SKU count: {len(PRODUCTS)}")
    cats = {}
    for rec in PRODUCTS:
        cats[rec["category"]] = cats.get(rec["category"], 0) + 1
    for c in sorted(cats):
        print(f"  {c}: {cats[c]}")
    print(f"wrote {FILTERHUB_OUT}")
    print(f"wrote {DATAHUB_OUT}")


if __name__ == "__main__":
    main()
